import { useState, useEffect } from "react"

function BooksFromTheServer() {
  const [books, setBooks] = useState([])

  useEffect(()=> {
    fetch("/to-read")
      .then(resp => resp.json)
      .then(setBooks)
  }, [])

  return (
    books
  )
}

export default function ToRead(){
  return (
    <>
      <h2>Books To read</h2>
      <div className="list-container">
        <div className="book-list">
          <ul>
            <BooksFromTheServer/> 
          </ul>
        </div>
      </div>
    </>
  )  
}
